CREATE TABLE "plan_overrides" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "plan_overrides_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" uuid DEFAULT app.uid() NOT NULL,
	"category_id" integer,
	"item_id" integer,
	"month" text NOT NULL,
	"amount" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "plan_overrides_user_category_month_unique" UNIQUE("user_id","category_id","month"),
	CONSTRAINT "plan_overrides_user_item_month_unique" UNIQUE("user_id","item_id","month"),
	CONSTRAINT "plan_overrides_target_check" CHECK ((category_id is null) <> (item_id is null)),
	CONSTRAINT "plan_overrides_amount_check" CHECK (amount >= 0),
	CONSTRAINT "plan_overrides_month_check" CHECK (month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$')
);
